pub static NAME_MAP: LazyLock<HashMap<String, EntityType>> = LazyLock::new(|| {
    let mut map = HashMap::new();
    for type_ in EntityType::VALUES {
        if let Some(name) = &type_.data().name {
            map.insert(name.to_lowercase(), type_);
        }
    }
    map
}); // paper-api/src/main/java/org/bukkit/entity/EntityType.java:222
pub static ID_MAP: LazyLock<HashMap<i16, EntityType>> = LazyLock::new(|| {
    let mut map = HashMap::new();
    for type_ in EntityType::VALUES {
        if type_.data().type_id > 0 {
            map.insert(type_.data().type_id, type_);
        }
    }
    map
}); // paper-api/src/main/java/org/bukkit/entity/EntityType.java:223
